import { TriggerDefinition } from '../../TriggerDefinition'
import { FlowObject } from '../../FlowTypes'
import { BooleanColumn, ReferenceColumn, StringColumn } from '../../../db'

export const slaTaskTrigger = TriggerDefinition({
    $id: 'f5ce00a873723300d70877186bf6a759',
    name: 'SLA Task',
    type: 'sla_task',
    outputs: {
        task_sla_record: ReferenceColumn({
            label: 'Task SLA Record',
            referenceTable: 'task_sla',
            mandatory: true,
        }),
        sla_flow_inputs: FlowObject({
            fields: {
                duration: StringColumn({
                    label: 'duration',
                    maxLength: 32,
                }),
                relative_duration_works_on: StringColumn({
                    label: 'relative_duration_works_on',
                    maxLength: 32,
                }),
                is_repair: BooleanColumn({
                    label: 'is_repair',
                    maxLength: 32,
                    default: 'false',
                }),
                duration_type: StringColumn({
                    label: 'duration_type',
                    maxLength: 32,
                }),
                name: StringColumn({
                    label: 'name',
                    maxLength: 32,
                }),
            },
            label: 'sla_flow_inputs',
        }),
    },
})
